rollback.sql:
DELETE FROM clinlims.system_role_privilege
WHERE privilege_id = (SELECT id FROM clinlims.system_privilege WHERE name = 'organization:view')
  AND system_role_id IN (SELECT id FROM clinlims.system_role WHERE name IN ('Results', 'Validation'));
